def line(x,y,a,b,extra=''):return f'<path d="M{x} {y}L{a} {b}" fill="none" {extra}/>'
def circle(x,y,r,fill=C,extra=''):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" {extra}/>'
def star(x,y,r=14,fill=Y):return path(f'M{x} {y-r}Q{x+3} {y-3} {x+r} {y}Q{x+3} {y+3} {x} {y+r}Q{x-3} {y+3} {x-r} {y}Q{x-3} {y-3} {x} {y-r}Z',fill)
