# Alt text is retained from V9's actual rendered story cards, including its overrides.
import subprocess,re
node=r'''const fs=require('fs'),vm=require('vm');const root={innerHTML:''},c={window:{},document:{getElementById:()=>root,querySelectorAll:()=>[],querySelector:()=>({style:{}}),documentElement:{scrollHeight:1000}},addEventListener:()=>{},innerHeight:800,scrollY:0,location:{hash:''}};for(const f of ['dist/stories.js','dist/versions/v9/v9.js'])vm.runInNewContext(fs.readFileSync(f,'utf8'),c);console.log(root.innerHTML);'''
rendered=subprocess.check_output(['node','-e',node],cwd=root,text=True)
alts={}
for card in re.finditer(r'<article[^>]*id="([^"]+)"[\s\S]*?</article>',rendered):
 images=re.findall(r'<img[^>]+alt="([^"]*)"',card[0]);alts[card[1]]=html.unescape(images[-1])
out=root/'dist/assets/story-graphics/v13';out.mkdir(parents=True,exist_ok=True)
for name,body in arts.items():
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 300" width="480" height="300" role="img" aria-labelledby="title"><title id="title">{html.escape(alts[name])}</title><defs><pattern id="stipple" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="{N}" opacity=".2"/></pattern></defs><ellipse cx="240" cy="268" rx="180" ry="14" fill="url(#stipple)"/><g stroke="{N}" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">{body}</g></svg>'''
 ET.fromstring(svg);(out/f'{name}.svg').write_text(svg)
print(f'Built {len(arts)} V9-based Flatland illustrations; original descriptions preserved')
